referenceSolutions.javascript:
export function solve(operations) {
  const listeners = [];
  return operations.map(([op, event, id]) => {
    if (op === "on" || op === "once") {
      listeners.push({ event, id, once: op === "once" });
      return null;
    }
    if (op === "off") {
      const i = listeners.findIndex((x) => x.event === event && x.id === id);
      if (i >= 0) listeners.splice(i, 1);
      return null;
    }
    const result = listeners.filter((x) => x.event === event).map((x) => x.id);
    for (let i = listeners.length - 1; i >= 0; i--)
      if (listeners[i].event === event && listeners[i].once) listeners.splice(i, 1);
    return result;
  });
}

